"""Core tests with fake callbacks and real media generated by ffmpeg.

Usage: python3 tests/test_core.py <media_dir> [en|it]   (media from tests/make_media.py)
"""

import io
import json
import os
import shutil
import sys
import tempfile

from PIL import Image

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "bridge"))
from core import FIELD_AUDIO, FIELD_FILE_ATTACHMENTS, FIELD_IMAGE, Core, Limits  # noqa: E402
from i18n import make_t  # noqa: E402
from media import AM_CODEC2_2400, AM_OPUS_OGG  # noqa: E402

MEDIA = sys.argv[1]
LANG = sys.argv[2] if len(sys.argv) > 2 else "en"
T = make_t(LANG)
DL = {"en": "/download", "it": "/scarica"}[LANG]
OTHER_DL = {"en": "/scarica", "it": "/download"}[LANG]

CHAT = -1001234
A, B, C, X = "a" * 32, "b" * 32, "c" * 32, "e" * 32     # A, B fixed recipients; C random LXMF user; X blocked
work = tempfile.mkdtemp()
spool = os.path.join(work, "spool")
os.makedirs(spool)
FILES = {"F_PHOTO": "foto.jpg", "F_VOICE": "vo10.ogg", "F_LONGVOICE": "vo130.ogg", "F_VID": "vid.mp4",
         "F_SMALL": "small.bin"}

lx, tg, fetched = [], [], []


def fetch(file_id, dest):
    fetched.append(file_id)
    if file_id not in FILES:
        raise RuntimeError("Bad Request: invalid file_id")
    shutil.copy(os.path.join(MEDIA, FILES[file_id]), dest)


def mk(lim=None, **kw):
    args = dict(lx_send=lambda d, t_, f: lx.append((d, t_, f)), tg_send=tg.append, tg_fetch=fetch,
                name_of=lambda h: {C: "Carlo"}.get(h), blocked=[X], log=lambda s: None, lang=LANG,
                version="Heimdall test")
    args.update(kw)
    return Core(os.path.join(work, "state.json"), spool, lim or Limits(), CHAT, [A, B], **args)


core = mk()
ok = 0


def check(cond, what):
    global ok
    if not cond:
        print("FAILED:", what)
        print("  lx:", [(d[:4], t_, list(f)) for d, t_, f in lx[-4:]])
        print("  tg:", tg[-3:])
        sys.exit(1)
    ok += 1
    print("ok  ", what)


def upd(**m):
    base = {"message_id": 1, "chat": {"id": CHAT, "type": "supergroup", "title": "Radio club"},
            "from": {"id": 7, "first_name": "Anna", "last_name": "Rossi"}, "date": 0}
    base.update(m)
    return {"update_id": 1, "message": base}


def last_to(dest):
    return [x for x in lx if x[0] == dest][-1]


print(f"== language: {LANG}")

# ---------------------------------------------------------------- Telegram -> LXMF
n = len(lx)
core.on_tg_update(upd(text="ciao a tutti"))
check(lx[n:] == [(A, "Anna Rossi: ciao a tutti", {}), (B, "Anna Rossi: ciao a tutti", {})],
      "group text goes to every fixed recipient")

n = len(lx)
core.on_tg_update(upd(chat={"id": -999, "type": "group", "title": "Other"}, text="spam"))
check(len(lx) == n, "other chats ignored")

core.on_tg_update(upd(photo=[{"file_id": "x", "file_size": 900}, {"file_id": "F_PHOTO", "file_unique_id": "u1",
                                                                       "file_size": 75000}], caption="guardate"))
d, txt, f = last_to(B)
img = f.get(FIELD_IMAGE)
check(img and img[0] == "webp" and len(img[1]) < 32 * 1024 and txt == "Anna Rossi: guardate", "photo -> low webp, caption kept")
check(max(Image.open(io.BytesIO(img[1])).size) == 320 and fetched[-1] == "F_PHOTO", "biggest size fetched, 320 px")
check(not [n_ for n_ in os.listdir(spool) if n_.startswith("tg-")], "spool cleaned")

core.on_tg_update(upd(voice={"file_id": "F_VOICE", "duration": 10, "file_size": 20000}))
a = last_to(A)[2].get(FIELD_AUDIO)
check(a and a[0] == AM_CODEC2_2400 and 2900 <= len(a[1]) <= 3100, "voice -> codec2 2400 inline")

core.on_tg_update(upd(voice={"file_id": "F_LONGVOICE", "duration": 130, "file_size": 260000}))
d, txt, f = last_to(A)
check(f == {} and f"{DL} 1" in txt and T("label_voice", secs="130", level=T("level_low")) in txt,
      f"long voice held: {txt!r}")

core.on_tg_update(upd(video={"file_id": "F_VID", "file_size": 180000, "mime_type": "video/mp4"}, caption="clip"))
d, txt, f = last_to(B)
check(f == {} and f"{DL} 2" in txt and "LoRa" in txt and fetched[-1] != "F_VID", f"video held, not downloaded yet: {txt!r}")

core.on_tg_update(upd(document={"file_id": "F_SMALL", "file_size": 5000, "file_name": "note.bin"}))
fa = last_to(A)[2].get(FIELD_FILE_ATTACHMENTS)
check(fa and fa[0][0] == "note.bin" and len(fa[0][1]) == 5000, "small document inline")

core.on_tg_update(upd(document={"file_id": "F_BIG", "file_size": 5_000_000, "file_name": "film.mkv"}))
check(T("media_too_big", head="", icon="", label="", size="", caption="").split()[-1].rstrip(".") in last_to(A)[1]
      or "Reticulum" in last_to(A)[1], "5 MB document: too big notice")

core.on_tg_update(upd(location={"latitude": 41.8, "longitude": 12.7}))
check("41.80000, 12.70000" in last_to(A)[1] and "openstreetmap" in last_to(A)[1], "location as text with link")
core.on_tg_update(upd(sticker={"file_id": "s", "emoji": "😀"}))
check(last_to(A)[1] == f"Anna Rossi: [{T('sticker')} 😀]", "sticker as text")
n = len(lx)
core.on_tg_update(upd(new_chat_members=[{"first_name": "Bob"}]))
check(len(lx) == n, "service messages not forwarded")
core.on_tg_update({"update_id": 9, "channel_post": {"chat": {"id": CHAT, "type": "channel", "title": "News"},
                                                    "author_signature": "Redazione", "text": "bollettino"}})
check(last_to(A)[1] == "Redazione: bollettino", "channel post with signature")

# ---------------------------------------------------------------- downloads
core.on_lxmf(A, f"{DL} 1", {})
a = last_to(A)[2].get(FIELD_AUDIO)
check(a and a[0] == AM_CODEC2_2400 and len(a[1]) > 32 * 1024, "held voice delivered to who asked")
core.on_lxmf(B, f"{OTHER_DL} 1", {})
check(last_to(B)[2].get(FIELD_AUDIO), "still available for the other recipient (other-language alias)")
core.on_lxmf(A, f"{DL} 2", {})
fa = last_to(A)[2].get(FIELD_FILE_ATTACHMENTS)
check(fa and fa[0][0] == "video.mp4" and fetched[-1] == "F_VID", "held video fetched on demand")
core.on_lxmf(C, f"{DL} 1", {})
check(last_to(C)[1] == T("not_allowed"), "non-recipients cannot download")
core.on_lxmf(A, f"{DL} 77", {})
check(last_to(A)[1] == T("download_none", n="77"), "unknown pending number")

# ---------------------------------------------------------------- LXMF -> Telegram
core.on_lxmf(C, "ciao dal LoRa <3", {})
check(tg[-1]["kind"] == "text" and tg[-1]["text"] == "<b>Carlo</b>: ciao dal LoRa &lt;3", "text posted with announced name, escaped")
core.on_lxmf("d" * 32, "chi c'è?", {})
check(tg[-1]["text"] == "<b>&lt;dddddddd&gt;</b>: chi c&#x27;è?", "unknown sender shown by short hash")
n = len(tg)
core.on_lxmf(X, "spam", {})
check(len(tg) == n, "blocked sender ignored")

buf = io.BytesIO()
Image.new("RGB", (320, 240), (200, 30, 30)).save(buf, "webp", quality=22)
core.on_lxmf(C, "foto", {FIELD_IMAGE: ["webp", buf.getvalue()]})
c = tg[-1]
check(c["kind"] == "photo" and open(c["path"], "rb").read(2) == b"\xff\xd8" and c["caption"] == "<b>Carlo</b>: foto",
      "webp -> jpeg photo with caption")
core.on_lxmf(C, "", {FIELD_AUDIO: [AM_CODEC2_2400, a[1] if a else b""]} if False else
             {FIELD_AUDIO: [AM_OPUS_OGG, open(os.path.join(MEDIA, "vo10.ogg"), "rb").read()]})
check(tg[-1]["kind"] == "voice" and open(tg[-1]["path"], "rb").read(4) == b"OggS", "opus -> voice")
held = last_to(B)[2][FIELD_AUDIO][1]
core.on_lxmf(C, "", {FIELD_AUDIO: [AM_CODEC2_2400, held]})
check(tg[-1]["kind"] == "voice" and open(tg[-1]["path"], "rb").read(4) == b"OggS", "codec2 -> voice")
core.on_lxmf(C, "guarda", {FIELD_FILE_ATTACHMENTS: [["clip.mp4", b"x" * 1000], ["doc.pdf", b"%PDF"]]})
check(tg[-2]["kind"] == "video" and tg[-2]["caption"] == "<b>Carlo</b>: guarda" and tg[-1]["kind"] == "document"
      and tg[-1]["filename"] == "doc.pdf", "attachments: video + document")
core.on_lxmf(C, "", {})
check(last_to(C)[1] == T("empty"), "empty message refused")
core.on_lxmf(C, "x" * 9000, {})
check(len(tg[-1]["text"]) <= 4000 and tg[-3]["text"].startswith("<b>Carlo</b>: xxx"), "long text split for Telegram")

core.tg_failed({"origin": C, "what": T("what_text")}, "Forbidden: bot is not a member")
check("Forbidden" in last_to(C)[1], "Telegram failure reported to the sender")

# ---------------------------------------------------------------- policies
lx2, tg2 = [], []
strict = mk(Limits(rate_per_min=2), senders="targets", lx_send=lambda d, t_, f: lx2.append((d, t_, f)),
            tg_send=tg2.append)
strict.on_lxmf(C, "ciao", {})
check(not tg2 and lx2[-1] == (C, T("not_allowed"), {}), "senders=targets: strangers refused")
strict.on_lxmf(A, "uno", {})
strict.on_lxmf(A, "due", {})
strict.on_lxmf(A, "tre", {})
check(len(tg2) == 2 and lx2[-1] == (A, T("rate_limited", n=2), {}), "rate limit per sender")

core.on_lxmf(C, "/join" if LANG == "en" else "/entra", {})
check(last_to(C)[1] == T("join_closed"), "subscriptions closed by default")
sub = mk(subscriptions=True)
sub.on_lxmf(C, "/entra", {})
check(C in sub.recipients(), "/join with subscriptions on")
n = len(lx)
sub.on_tg_update(upd(text="per tutti"))
check(sorted(d for d, _, _ in lx[n:]) == sorted([A, B, C]), "subscriber receives the group")
sub.on_lxmf(A, "/leave", {})
check(last_to(A)[1] == T("join_fixed"), "fixed recipients cannot leave")
sub.on_lxmf(C, "/esci", {})
check(C not in sub.recipients(), "/leave")

ec = mk(echo=True)
n = len(lx)
ec.on_lxmf(A, "eco", {})
check([(d, t_) for d, t_, _ in lx[n:]] == [(B, "<aaaaaaaa>: eco")], "echo to the other LXMF recipients only")

# ---------------------------------------------------------------- quality and step-down
q = mk(Limits(quality_img="medium", quality_audio="medium"))
q.on_tg_update(upd(photo=[{"file_id": "F_PHOTO", "file_size": 75000}]))
img = last_to(A)[2].get(FIELD_IMAGE)
check(img and max(Image.open(io.BytesIO(img[1])).size) == 640, "quality_img=medium: 640 px")
q.on_tg_update(upd(voice={"file_id": "F_VOICE", "duration": 10, "file_size": 20000}))
a2 = last_to(A)[2].get(FIELD_AUDIO)
check(a2 and a2[0] == AM_OPUS_OGG, "quality_audio=medium: opus")
small = mk(Limits(quality_img="high", max_file_mb=0.003))
small.on_tg_update(upd(photo=[{"file_id": "F_PHOTO", "file_size": 75000}]))
d, txt, f = last_to(A)
check(T("reduced_note", level=T("level_low")) in txt or (f.get(FIELD_IMAGE) and len(f[FIELD_IMAGE][1]) <= 3072),
      "too big at high: steps down")

# ---------------------------------------------------------------- commands, state
core.tg_status = "ok"
core.on_lxmf(C, "/stato", {})
check(str(CHAT) in last_to(C)[1] and T("tg_ok") in last_to(C)[1], "/status")
core.on_lxmf(C, "/aiuto", {})
check(last_to(C)[1] == T("help", where=T("where_group")), "/help")
# ---------------------------------------------------------------- /repeat N
hspool = os.path.join(work, "hspool")
os.makedirs(hspool)
hlx = []
h = Core(os.path.join(work, "h.json"), hspool, Limits(history_max=4, history_h=1), CHAT, [A, B],
         lx_send=lambda d, t_, f: hlx.append((d, t_, f)), tg_send=lambda c: None, tg_fetch=fetch,
         log=lambda s: None, lang=LANG, subscriptions=True)
RP = {"en": "/repeat", "it": "/ripeti"}[LANG]
OTHER_RP = {"en": "/ripeti", "it": "/repeat"}[LANG]
for word in ("uno", "due"):
    h.on_tg_update(upd(text=word))
h.on_tg_update(upd(photo=[{"file_id": "F_PHOTO", "file_unique_id": "u9", "file_size": 75000}], caption="pic"))
h.on_lxmf(A, "/status", {})                       # only A gets this reply, and it is in A's history only
h.on_tg_update(upd(text="cinque"))
check(len(h.st["history"][A]) == 4 and len(h.st["history"][B]) == 4, "per-recipient history capped at history_max")
n = len(hlx)
h.on_lxmf(A, RP, {})
check(hlx[n:] == [(A, T("repeat_usage"), {})], "bare /repeat: usage, nothing repeated")
h.on_lxmf(A, RP + " 0", {})
h.on_lxmf(A, RP + " abc", {})
check(hlx[-1][1] == T("repeat_usage") and hlx[-2][1] == T("repeat_usage"), "/repeat 0 and /repeat abc: usage")
check(h.st["history"][A][-1]["text"].endswith("cinque"), "usage replies and repeats are not recorded")
n = len(hlx)
h.on_lxmf(A, RP + " 4", {})
out = hlx[n:]
check(len(out) == 5 and all(x[0] == A for x in out) and out[0][1] == T("repeat_start", n=4)
      and out[1][1].startswith("\u21bb ") and FIELD_IMAGE in out[2][2] and "Telegram:" in out[3][1]
      and out[4][1].endswith("cinque"), "/repeat 4 for A: oldest first, photo with field, /status reply included")
n = len(hlx)
h.on_lxmf(B, OTHER_RP + " 4", {})
outb = hlx[n:]
check(len(outb) == 5 and all(x[0] == B for x in outb) and not any("Telegram:" in x[1] for x in outb)
      and outb[1][1].endswith("uno"), "other-language alias; B gets only what was sent to B")
h.on_lxmf(C, RP + " 3", {})
check(hlx[-1][0] == C and hlx[-1][1] == T("not_allowed") and C not in h.st["history"], "non-recipient: refused, nothing stored")
h.on_lxmf(C, "/join", {})
h.on_lxmf(C, RP + " 3", {})
check(hlx[-1][1].startswith(T("repeat_start", n=1)) or len(h.st["history"][C]) == 1,
      "a new subscriber only has what was sent to them after joining")
for hist in h.st["history"].values():
    for e in hist:
        e["ts"] -= 2 * 3600
h.expire_pending()
check(h.st["history"] == {} and not any(n_.startswith("hist-") for n_ in os.listdir(hspool)),
      "history expires after history_h, blobs removed")
h.on_lxmf(A, RP + " 3", {})
check(hlx[-1][1] == T("repeat_none"), "/repeat with empty history")
off = Core(os.path.join(work, "off.json"), hspool, Limits(history_max=0), CHAT, [A], lambda *a: None,
           lambda c: None, fetch, log=lambda s: None, lang=LANG)
off.on_tg_update(upd(text="x"))
check(off.st["history"] == {}, "history_max = 0 disables the history")

core.on_lxmf(C, "/boh", {})
check(last_to(C)[1] == T("unknown_command", cmd="/boh"), "unknown command")
core.on_tg_update(upd(migrate_to_chat_id=-100777))
check(core.chat_id == -100777, "group -> supergroup migration followed")
again = mk()
check(again.chat_id == -100777 and "1" in again.st["pending"], "state persisted (migration, pending)")
moved = Core(os.path.join(work, "state.json"), spool, Limits(), -100555, [A], lambda *a: None, lambda c: None,
             fetch, log=lambda s: None)
check(moved.chat_id == -100555, "a new chat_id in the config wins over an old migration")
core.st["pending"]["1"]["t"] = 0
core.expire_pending()
check("1" not in core.st["pending"], "held media expire")

print(f"\n{ok} checks passed")
shutil.rmtree(work)
